CREATE DATABASE IF NOT EXISTS saranarazaq CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE saranarazaq;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS detilpeminjaman,peminjaman,peminjam,alat,kategori,asal,user;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE user (iduser INT AUTO_INCREMENT PRIMARY KEY,namauser VARCHAR(50) NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,nohp VARCHAR(20) DEFAULT '',alamat VARCHAR(150) DEFAULT '',foto VARCHAR(100) DEFAULT 'default.png',role ENUM('admin','petugas','peminjam') NOT NULL DEFAULT 'petugas');
CREATE TABLE asal (idasal INT AUTO_INCREMENT PRIMARY KEY,namaasal VARCHAR(50) NOT NULL);
CREATE TABLE kategori (idkategori INT AUTO_INCREMENT PRIMARY KEY,namakategori VARCHAR(50) NOT NULL,foto VARCHAR(100) NULL);
CREATE TABLE peminjam (idpeminjam INT AUTO_INCREMENT PRIMARY KEY,iduser INT NULL,idasal INT NOT NULL,namapeminjam VARCHAR(50) NOT NULL,kelas VARCHAR(30) NOT NULL,nohp VARCHAR(20) NOT NULL,lokasi VARCHAR(100) NOT NULL,CONSTRAINT fk_peminjam_user FOREIGN KEY(iduser) REFERENCES user(iduser) ON DELETE SET NULL,CONSTRAINT fk_peminjam_asal FOREIGN KEY(idasal) REFERENCES asal(idasal));
CREATE TABLE alat (idalat INT AUTO_INCREMENT PRIMARY KEY,idkategori INT NOT NULL,namaalat VARCHAR(100) NOT NULL,jumlah INT NOT NULL DEFAULT 0,kondisi VARCHAR(30) NOT NULL,lokasi VARCHAR(100) NOT NULL,foto VARCHAR(100) DEFAULT 'default.png',CONSTRAINT fk_alat_kategori FOREIGN KEY(idkategori) REFERENCES kategori(idkategori));
CREATE TABLE peminjaman (idpeminjaman INT AUTO_INCREMENT PRIMARY KEY,iduser INT NOT NULL,idpeminjam INT NOT NULL,tanggalpinjam DATE NOT NULL,tanggalrencana DATE NOT NULL,tanggalpengembalian DATE NULL,status VARCHAR(30) NOT NULL DEFAULT 'Menunggu',bukti_pengembalian VARCHAR(100) NULL,CONSTRAINT fk_peminjaman_user FOREIGN KEY(iduser) REFERENCES user(iduser),CONSTRAINT fk_peminjaman_peminjam FOREIGN KEY(idpeminjam) REFERENCES peminjam(idpeminjam));
CREATE TABLE detilpeminjaman (iddetilpeminjaman INT AUTO_INCREMENT PRIMARY KEY,idpeminjaman INT NOT NULL,idalat INT NOT NULL,jumlahpinjam INT NOT NULL,kondisi VARCHAR(30) NOT NULL,CONSTRAINT fk_detil_peminjaman FOREIGN KEY(idpeminjaman) REFERENCES peminjaman(idpeminjaman) ON DELETE CASCADE,CONSTRAINT fk_detil_alat FOREIGN KEY(idalat) REFERENCES alat(idalat));
